      let axDes = kpX * clamp(ex, -clampEx, clampEx) + kdX * (vxDes - v.x) - 0.16 * axCurr;
      let azDes = kpZ * clamp(ez, -clampEz, clampEz) + kdZ * (vzDes - v.z) + 3.2 * intZ - 0.20 * azCurr;
      let ayDes = kpY * clamp(ey, -clampEy, clampEy) + kdY * (vyDes - v.y) + 2.4 * intY;

      if (gustDelta > 1.2) {
        axDes += clamp(-0.18 * innovX, -1.5, 1.5);
        azDes += clamp(-0.18 * innovZ, -1.5, 1.5);
      }

      axDes = clamp(axDes, -5.6, 5.6);
      azDes = clamp(azDes, -5.6, 5.6);
      ayDes = clamp(ayDes, -4.4, 5.6);

      // Floor impact protection: keep touchdown speed well below 0.85 m/s limit
      if (p.y < 0.28 && v.y < -0.38) {
        ayDes = Math.max(ayDes, -7.0 * (v.y + 0.30));
      }

      const axThrust = axDes + dragCoeff * v.x - windFastX;
      const azThrust = azDes + dragCoeff * v.z - windFastZ;
      const ayThrust = clamp(9.81 + ayDes + dragCoeff * v.y, 2.2, 22.0);

      const bodyXRatio = cy * axThrust - sy * azThrust;
      const bodyZRatio = sy * axThrust + cy * azThrust;

      let pitchDes = clamp(Math.atan2(bodyXRatio, ayThrust), -0.52, 0.52);
      let rollDes = clamp(-Math.atan2(bodyZRatio, Math.hypot(bodyXRatio, ayThrust)), -0.52, 0.52);

      if (obs.gateIndex === 3 && p.y < 0.16) {
        pitchDes = clamp(pitchDes, -0.22, 0.22);
        rollDes = clamp(rollDes, -0.22, 0.22);
      }

      let thrust = clamp(ayThrust / (thrustScale * dirYNow), 0.05, 1.0);

      let totBiasRoll, totBiasPitch;
      if (pinned) {
        // Pin pad with low thrust and keep tilt strictly inside landingTilt < 0.18
        thrust = 0.06;
        pitchDes = clamp(pitchDes * 0.30, -0.08, 0.08);
        rollDes = clamp(rollDes * 0.30, -0.08, 0.08);
        totBiasRoll = biasPerThrustRoll * thrust;
        totBiasPitch = biasPerThrustPitch * thrust;
      } else {
        totBiasRoll = biasPerThrustRoll * thrust + biasResRoll;
        totBiasPitch = biasPerThrustPitch * thrust + biasResPitch;
      }

      const roll = clamp(rollDes - (3.2 * r.roll + 22 * simIntRoll + totBiasRoll) / 65, -0.6, 0.6);
      const pitch = clamp(pitchDes - (3.2 * r.pitch + 22 * simIntPitch + totBiasPitch) / 65, -0.6, 0.6);
