          const azPred = thrustScale * lagThrust * dirZ - dragCoeff * midVelZ;
          const wxMeas = (v.x - prevVel.x) / 0.01 - axPred;
          const wzMeas = (v.z - prevVel.z) / 0.01 - azPred;

