          totBiasPitch = biasPerThrustPitch * thrust;
        } else {
          totBiasRoll = biasPerThrustRoll * thrust + biasResRoll;
          totBiasPitch = biasPerThrustPitch * thrust + biasResPitch;
        }

        const roll = clamp(rollDes - (cfg.kdRate * r.roll + 22 * simIntRoll + totBiasRoll) / 65, -0.6, 0.6);
        const pitch = clamp(pitchDes - (cfg.kdRate * r.pitch + 22 * simIntPitch + totBiasPitch) / 65, -0.6, 0.6);
