        prevVel = { x: v.x, y: v.y, z: v.z };
        prevAtt = { roll: a.roll, pitch: a.pitch, yaw: a.yaw };
        prevRates = { roll: r.roll, pitch: r.pitch, yaw: r.yaw };
        prevAction = { thrust, roll, pitch, yawRate };

